const escapeHtml = (value: unknown): string =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const formatLocalDateFilename = (now: Date): string =>
  `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

const isClientTrayDndActive = (policy: TrayAlertPolicy): boolean => {
  if (policy.dndEnabled) return true;
  if (policy.dndUntilMs && Date.now() < policy.dndUntilMs) return true;
  if (policy.quietHoursEnabled && policy.quietStart && policy.quietEnd) {
    const parseHm = (hm: string): number | null => {
      const m = /^(\d{1,2}):(\d{2})$/.exec(hm.trim());
      if (!m) return null;
      const h = Number(m[1]);
      const min = Number(m[2]);
      if (h < 0 || h > 23 || min < 0 || min > 59) return null;
      return h * 60 + min;
    };
    const startMin = parseHm(policy.quietStart);
    const endMin = parseHm(policy.quietEnd);
    if (startMin !== null && endMin !== null && startMin !== endMin) {
      const now = new Date();
      const curMin = now.getHours() * 60 + now.getMinutes();
      if (startMin > endMin) {
        if (curMin >= startMin || curMin < endMin) return true;
      } else if (curMin >= startMin && curMin < endMin) {
        return true;
      }
    }
  }
  return false;
};

export interface DeviceClassificationContext {
  ip?: string;
  hostname?: string;
  mdns?: string;
  webTitle?: string;
  upnp?: string;
  snmp?: string;
  mac?: string;
  httpHeaders?: string;
  realVendor?: string;
  chipsetVendor?: string;
  vendorSource?: string;
  ouiBlockType?: string;
  ouiPrefix?: string;
  isRandomizedMac?: boolean;
  lang?: 'ko' | 'en';
}

export interface DeviceClassification {
  type: string;
  os: string;
  model?: string;
  deviceCategory?: string;
  realVendor?: string;
  chipsetVendor?: string;
  vendorSource?: string;
  realVendorConfidence?: number;
  chipsetConfidence?: number;
  confidenceScore?: number;
  priorityRank?: number;
  ouiBlockType?: OUIBlockType | string;
  ouiPrefix?: string;
  isRandomizedMac?: boolean;
  isChipsetOem?: boolean;
  classificationReasons?: ClassificationEvidence[];
}

const classifyDevice = (
  vendor: string,
  openPorts: number[] = [],
  s: any,
  context?: DeviceClassificationContext
): DeviceClassification => {
  return classifyDeviceHybrid(vendor, openPorts, s, context);
};

